import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ProfilePage.css";

const ProfilePage = () => {
  const [profile, setProfile] = useState(null);
  const [lookups, setLookups] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("accessToken");
    if (!token) {
      setError("You must log in first.");
      return;
    }

    const fetchProfile = async () => {
      try {
        // ✅ Lấy thông tin người dùng từ API mới
        const res = await axios.get("http://localhost:3030/api/user/profile", {
          headers: { Authorization: `Bearer ${token}` },
        });
        setProfile(res.data);
      } catch (err) {
        console.error("Profile fetch error:", err);
        setError("Failed to load profile data.");
      }
    };

    const fetchRecentLookups = async () => {
      try {
        const res = await axios.get("http://localhost:3030/api/dict/recent", {
          headers: { Authorization: `Bearer ${token}` },
        });
        setLookups(res.data);
      } catch (err) {
        console.error("Lookup fetch error:", err);
      }
    };

    fetchProfile();
    fetchRecentLookups();
  }, []);

  if (error) {
    return (
      <div className="profile-container">
        <h2>TalkMate</h2>
        <p className="error">{error}</p>
      </div>
    );
  }

  if (!profile) {
    return (
      <div className="profile-container">
        <h2>Loading profile...</h2>
      </div>
    );
  }

  return (
    <div className="profile-container">
      <h2>👤 {profile.username || "UnknownUser"}'s Profile</h2>

      <section className="profile-section">
        <h3>Basic Infomation</h3>
        <p>
          <strong>User name:</strong> {profile.username}
        </p>
        <p>
          <strong>Email:</strong> {profile.email}
        </p>
      </section>

      <section className="profile-section">
        <h3>Recent Lookups (7 days)</h3>
        {lookups.length === 0 ? (
          <p>No lookup history yet.</p>
        ) : (
          <ul className="lookup-list">
            {lookups.map((item) => (
              <li key={item.id} className="lookup-item">
                <span className="word">{item.word}</span>
                <span className="date">
                  {new Date(item.createdAt).toLocaleDateString("en-GB")}
                </span>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
};

export default ProfilePage;
